// Edit these two values after pasting.
const relayUrl = 'https://YOUR-RELAY-URL';
const secret = 'YOUR-SHARED-SECRET';
return $input.all().map((i) => ({ json: { ...i.json, config: { relayUrl: relayUrl.replace(/[/]+$/, ''), secret } } }));

const raw = $input.first().json;
const secret = $('Config').first().json.config.secret;
const given = (raw.headers && (raw.headers['x-afterlink-ingress-secret'] || raw.headers['x-afterlink-ingress-secret'.toLowerCase()])) || '';
if (given !== secret) return [{ json: { authorized: false } }];
const p = raw.body && typeof raw.body === 'object' ? raw.body : {};
const r = p.record && typeof p.record === 'object' ? p.record : null;
if (!r || typeof r.mission !== 'string') return [{ json: { authorized: true, valid: false } }];
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[ch]);
const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);
const arr = (v) => (Array.isArray(v) ? v : []);
const conflicts = arr(r.conflicts), episodes = arr(r.episodes), cons = arr(r.conservation), timeline = arr(r.timeline), unknowns = arr(r.unknowns);
const violations = conflicts.filter((c) => c.severity === 'violation').length;
const when = (ms) => (ms ? new Date(ms).toISOString().replace('T', ' ').slice(0, 19) + ' UTC' : 'open');
const generatedAt = new Date().toISOString();
const md = [
  '# After-action report: ' + r.mission, '',
  'Generated ' + generatedAt, '',
  p.narrative ? String(p.narrative) + '\n' : '',
  '## Summary', '',
  '- Events reconciled: ' + num(r.events),
  '- Actors: ' + num(r.actors),
  '- Tasks completed while HQ was blind: ' + num(r.doneWhileHqBlind),
  '- Unsafe commitments refused: ' + num(r.refusedUnsafe),
  '- Duplicate efforts prevented: ' + num(r.duplicatesPrevented),
  '- Conflicts: ' + conflicts.length + ' (' + violations + ' invariant violations)', '',
  '## Partitions', '',
  ...(episodes.length ? episodes.map((e) => '- ' + when(e.from) + ' to ' + when(e.to) + ': ' + num(e.tasksDone) + ' tasks done, ' + num(e.decisions) + ' decisions, ' + num(e.refusals) + ' refusals') : ['- None recorded']), '',
  '## Resource conservation', '',
  ...(cons.length ? cons.map((c) => '- ' + c.resource + ': issued ' + num(c.issued) + ', committed ' + num(c.committed) + ', held ' + num(c.held) + ', in transit ' + num(c.inTransit) + ' (' + (c.ok ? 'balanced' : 'NOT balanced') + ')') : ['- None recorded']), '',
  '## Conflicts', '',
  ...(conflicts.length ? conflicts.map((c) => '- [' + c.severity + '] ' + c.kind + ': ' + c.summary + (c.resolved ? ' Resolved: ' + (c.resolution || 'yes') : ' Unresolved')) : ['- None']), '',
  '## Unknowns', '',
  ...(unknowns.length ? unknowns.map((u) => '- ' + u) : ['- None']), '',
  '## Timeline (' + timeline.length + ' entries)', '',
  ...timeline.slice(0, 200).map((t) => '- ' + when(t.at) + ' [' + t.team + '] ' + t.label + (t.hiddenFromHq ? ' (HQ did not see this)' : '')),
].join('\n');
const li = (items) => '<ul>' + items.map((i) => '<li>' + esc(i) + '</li>').join('') + '</ul>';
const html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>After-action report</title><style>body{font:16px/1.55 system-ui,sans-serif;max-width:48rem;margin:2rem auto;padding:0 1rem;color:#111;background:#fff}h1{font-size:1.5rem}h2{margin-top:2rem;font-size:1.1rem}li{margin:.2rem 0}.meta{color:#555}@media(prefers-color-scheme:dark){body{background:#111;color:#eee}.meta{color:#aaa}}</style></head><body>'
  + '<h1>After-action report: ' + esc(r.mission) + '</h1><p class="meta">Generated ' + esc(generatedAt) + '</p>'
  + (p.narrative ? '<p>' + esc(p.narrative) + '</p>' : '')
  + '<h2>Summary</h2>' + li(['Events reconciled: ' + num(r.events), 'Actors: ' + num(r.actors), 'Tasks completed while HQ was blind: ' + num(r.doneWhileHqBlind), 'Unsafe commitments refused: ' + num(r.refusedUnsafe), 'Duplicate efforts prevented: ' + num(r.duplicatesPrevented), 'Conflicts: ' + conflicts.length + ' (' + violations + ' invariant violations)'])
  + '<h2>Partitions</h2>' + li(episodes.length ? episodes.map((e) => when(e.from) + ' to ' + when(e.to) + ': ' + num(e.tasksDone) + ' tasks done, ' + num(e.decisions) + ' decisions, ' + num(e.refusals) + ' refusals') : ['None recorded'])
  + '<h2>Resource conservation</h2>' + li(cons.length ? cons.map((c) => c.resource + ': issued ' + num(c.issued) + ', committed ' + num(c.committed) + ', held ' + num(c.held) + ', in transit ' + num(c.inTransit) + ' (' + (c.ok ? 'balanced' : 'not balanced') + ')') : ['None recorded'])
  + '<h2>Conflicts</h2>' + li(conflicts.length ? conflicts.map((c) => '[' + c.severity + '] ' + c.kind + ': ' + c.summary + (c.resolved ? ' Resolved.' : ' Unresolved.')) : ['None'])
  + '<h2>Unknowns</h2>' + li(unknowns.length ? unknowns : ['None'])
  + '<h2>Timeline</h2>' + li(timeline.slice(0, 200).map((t) => when(t.at) + ' [' + t.team + '] ' + t.label + (t.hiddenFromHq ? ' (HQ did not see this)' : '')))
  + '</body></html>';
const store = $getWorkflowStaticData('global');
const entry = { mission: r.mission, generatedAt, markdown: md, html };
store.latest = entry;
store.history = [{ mission: r.mission, generatedAt, conflicts: conflicts.length }, ...(store.history || [])].slice(0, 20);
return [{ json: { authorized: true, valid: true, mission: r.mission, generatedAt, subject: 'After-action report: ' + r.mission, markdown: md, html, published: true, reportUrl: 'https://' + (raw.headers.host || '') + '/webhook/afterlink/report' } }];

const store = $getWorkflowStaticData('global');
const l = store.latest;
const html = l ? l.html : '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>After-action report</title></head><body style="font:16px system-ui;max-width:40rem;margin:2rem auto;padding:0 1rem"><h1>After-action report</h1><p>No report has been published yet.</p></body></html>';
return [{ json: { html } }];
